<?php
declare(strict_types=1);require __DIR__.'/app.php';$token=(string)($_GET['token']??$_POST['token']??'');$error='';$done=false;$valid=false;
if(preg_match('/^[a-f0-9]{64}$/',$token)){$s=db()->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1');$s->execute([hash('sha256',$token)]);$reset=$s->fetch();$valid=(bool)$reset;}
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{verify_csrf();if(!$valid)throw new RuntimeException('El enlace venció o ya fue utilizado. Solicita uno nuevo.');$password=(string)($_POST['password']??'');if(strlen($password)<10)throw new RuntimeException('La contraseña debe tener al menos 10 caracteres.');if($password!==(string)($_POST['confirm_password']??''))throw new RuntimeException('Las contraseñas no coinciden.');db()->beginTransaction();db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?')->execute([$reset['id']]);db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$reset['user_id']]);db()->commit();$done=true;$valid=false;
  }catch(Throwable $e){try{if(db()->inTransaction())db()->rollBack();}catch(Throwable $ignored){}$error=$e instanceof PDOException?'No se pudo actualizar la contraseña.':$e->getMessage();}
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nueva contraseña · Mutatio</title><link rel="stylesheet" href="assets/app.css"><link rel="stylesheet" href="assets/extra.css"></head><body class="login-page"><main class="auth-wrap"><a class="login-brand" href="index.php"><span class="brand-mark">M</span><span>MUTATIO <small>TRAINING CLUB</small></span></a><section class="auth-card"><span class="eyebrow">SEGURIDAD DE CUENTA</span><h1>Nueva contraseña</h1><?php if($done): ?><div class="alert">Contraseña actualizada. Ya puedes iniciar sesión.</div><a class="btn primary wide" href="index.php?view=login">Ir al inicio de sesión ↗</a><?php elseif(!$valid&&!$error): ?><div class="alert error">El enlace venció o ya fue utilizado. Solicita uno nuevo.</div><a href="forgot-password.php">Solicitar otro enlace</a><?php else: ?><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="token" value="<?=h($token)?>"><label>Nueva contraseña (10 caracteres o más)<input type="password" name="password" minlength="10" required autocomplete="new-password"></label><label>Confirmar contraseña<input type="password" name="confirm_password" minlength="10" required autocomplete="new-password"></label><button class="btn primary wide">Guardar contraseña <span>↗</span></button></form><?php endif; ?><p class="auth-foot"><a href="index.php?view=login">← Volver al inicio de sesión</a></p></section></main></body></html>
